INSERT INTO public.email_templates (template_key, subject, description, html_body)
VALUES (
  'new_review',
  'New Review: {{rating_stars}} by {{customer_name}}',
  'Sent when a customer submits a new review',
  '<!DOCTYPE html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"></head><body style="margin:0;padding:0;background:#f9f5f0;font-family:Georgia,serif"><div style="max-width:520px;margin:40px auto;background:#fff;border-radius:16px;overflow:hidden;box-shadow:0 4px 24px rgba(0,0,0,0.08)"><div style="background:#3c2415;padding:28px 32px;text-align:center"><h1 style="color:#d4a574;margin:0;font-size:20px;letter-spacing:1px">⭐ New Review Submitted</h1></div><div style="padding:32px"><p style="color:#3c2415;font-size:15px;margin:0 0 20px">A customer has submitted a new review that needs your attention.</p><div style="background:#f9f5f0;border-radius:12px;padding:20px;margin-bottom:20px"><p style="margin:0 0 8px;font-size:14px;color:#8b7355"><strong>Reviewer:</strong></p><p style="margin:0 0 16px;font-size:16px;color:#3c2415;font-weight:bold">{{customer_name}}</p><p style="margin:0 0 8px;font-size:14px;color:#8b7355"><strong>Rating:</strong></p><p style="margin:0 0 16px;font-size:20px">{{rating_stars}}</p><p style="margin:0 0 8px;font-size:14px;color:#8b7355"><strong>Comment:</strong></p><p style="margin:0;font-size:14px;color:#3c2415;line-height:1.6">{{comment}}</p></div><a href="https://flaroma.lovable.app/admin/reviews" style="display:block;text-align:center;background:#3c2415;color:#d4a574;text-decoration:none;padding:14px 24px;border-radius:10px;font-size:14px;font-weight:bold;letter-spacing:0.5px">Review in Dashboard →</a></div><div style="padding:16px 32px;background:#f9f5f0;text-align:center"><p style="margin:0;font-size:11px;color:#8b7355">Flaroma Alerts • alerts@flaroma.bd</p></div></div></body></html>'
)
ON CONFLICT DO NOTHING;